pub fn routebuilder_cors(
    resource: rustler::ResourceArc<RouteBuilder>,
    cors: Option<String>,
) -> Result<ResourceArc<RouteBuilder>, String> {
    let cors_core: Option<spikard::CorsConfig> = cors
        .map(|s| serde_json::from_str::<spikard::CorsConfig>(&s))
        .transpose()
        .map_err(|error| format!("failed to deserialize parameter `cors` for `routebuilder_cors`: {error}"))?;
    Ok(ResourceArc::new(RouteBuilder {
        inner: Arc::new(std::sync::RwLock::new(
            resource
                .inner
                .read()
                .unwrap_or_else(|e| e.into_inner())
                .clone()
                .cors(cors_core.unwrap_or_default()),
        )),
    }))
}

